// What did the student send? A typed message, or a tap on one of our buttons?
// Output: { chatId, name, action, value, callbackId, messageId }
const update = $('💬 Student sends a message').first().json;

// Typed commands -> action
const COMMANDS = { '/start': 'start', '/class': 'start', '/today': 'today', '/tomorrow': 'tomorrow',
                   '/next': 'next', '/week': 'week', '/stop': 'stop', '/help': 'help' };
// The big menu buttons simply send their label as a message
const MENU_BUTTONS = { 'Today': 'today', 'Tomorrow': 'tomorrow', 'Next class': 'next',
                       'Week': 'week', 'Change class': 'start' };
// Buttons under a message send short "callback data", e.g. "s:SOICT" or "c:1299"
const CALLBACKS = { home: 'start', s: 'school', p: 'program', c: 'section', b: 'batch', d: 'day' };

if (update.callback_query) {                        // a button was tapped
  const tap = update.callback_query;
  if (!tap.message) return [];
  const [kind, ...rest] = (tap.data || '').split(':');
  return [{ json: {
    chatId: tap.message.chat.id,
    name: tap.from.first_name || '',
    action: CALLBACKS[kind] || 'help',
    value: rest.join(':'),
    callbackId: tap.id,
    messageId: tap.message.message_id,             // so we can edit that message
  } }];
}

const message = update.message || {};              // a typed message
if (!message.chat) return [];
const text = (message.text || '').trim();
const firstWord = text.split(/\s+/)[0].split('@')[0].toLowerCase();   // "/today@MyBot" -> "/today"

let action = 'help';
if (MENU_BUTTONS[text]) action = MENU_BUTTONS[text];
else if (COMMANDS[firstWord]) action = COMMANDS[firstWord];
else if (text && !text.startsWith('/')) action = 'search';            // maybe they typed "BCS-I-A"

return [{ json: {
  chatId: message.chat.id,
  name: (message.from || {}).first_name || '',
  action,
  value: text,
  callbackId: null,
  messageId: null,
} }];

// The class picker: school -> program -> class.
// Also handles typed class names like "bcs-i-a".
const who = $('🧠 Understand message').first().json;
const student = $('👤 Find student').first().json;          // {} if no class picked yet

// Every class slot in the timetable - we only need "which class belongs where" here
const rows = JSON.parse($('📥 Fetch GBU timetable').first().json.data).map(r => ({
  school: String(r.school ?? '').trim(),
  programId: String(r.program_id ?? '').trim(),
  program: String(r.program_name ?? '').trim(),
  sectionId: String(r.Section_Id ?? '').trim(),
  section: String(r.SectionName ?? '').trim(),
}));

// Little helpers
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const uniqueBy = (list, key) => [...new Map(list.map(x => [key(x), x])).values()];
const rowsOf = (buttons, perRow) => {
  const out = [];
  for (let i = 0; i < buttons.length; i += perRow) out.push(buttons.slice(i, i + perRow));
  return out;
};
const button = (text, data) => ({ text, callback_data: data });
const simplify = s => s.toLowerCase().replace(/[^a-z0-9]/g, '');

let text, buttons;

if (who.action === 'school') {            // Step 2: programs in the chosen school
  const programs = uniqueBy(rows.filter(r => r.school === who.value), r => r.programId)
    .sort((a, b) => byText(a.program, b.program));
  text = `<b>Step 2 of 3</b>: your program in <b>${esc(who.value)}</b>?`;
  buttons = [...programs.map(p => [button(p.program, `p:${p.programId}`)]), [button('Back', 'home')]];
}

if (who.action === 'program') {           // Step 3: classes (sections) in the chosen program
  const sections = uniqueBy(rows.filter(r => r.programId === who.value), r => r.sectionId)
    .sort((a, b) => byText(a.section, b.section));
  if (sections.length) {
    text = `<b>Step 3 of 3</b>: your class in <b>${esc(sections[0].program)}</b>?`;
    buttons = [...rowsOf(sections.map(s => button(s.section, `c:${s.sectionId}`)), 3),
               [button('Back', `s:${sections[0].school}`)]];
  }
}

if (who.action === 'search') {            // They typed something, e.g. "bcs-i-a"
  const wanted = simplify(who.value);
  const matches = wanted.length < 2 ? [] :
    uniqueBy(rows.filter(r => simplify(r.section).includes(wanted)), r => r.sectionId)
      .sort((a, b) => (simplify(a.section) !== wanted) - (simplify(b.section) !== wanted) || byText(a.section, b.section))
      .slice(0, 12);
  if (matches.length) {
    text = `Classes matching "${esc(who.value)}" - tap yours:`;
    buttons = rowsOf(matches.map(s => button(s.section, `c:${s.sectionId}`)), 3);
  } else {
    text = `I couldn't find a class called "${esc(who.value)}".\n\n` +
           `Tap /start to pick it from a list, or /help to see what I can do.`;
  }
}

if (!text) {                              // Step 1 (/start): the list of schools
  const schools = [...new Set(rows.map(r => r.school).filter(Boolean))].sort(byText);
  text = `Hi${who.name ? ' ' + esc(who.name) : ''}! I'm the <b>GBU Timetable Bot</b>.\n` +
         `I'll send you your timetable every morning and remind you before every class.\n\n` +
         (student.section ? `You're currently in <b>${esc(student.section)}</b>. Pick again to change it.\n\n` : '') +
         `<b>Step 1 of 3</b>: which school are you in?`;
  buttons = rowsOf(schools.map(s => button(s, `s:${s}`)), 3);
}

// Reply. If they tapped a button we update that same message, otherwise we send a new one.
const body = { chat_id: who.chatId, text, parse_mode: 'HTML' };
if (buttons) body.reply_markup = { inline_keyboard: buttons };
if (!who.callbackId) return [{ json: { method: 'sendMessage', body } }];
return [
  { json: { method: 'answerCallbackQuery', body: { callback_query_id: who.callbackId } } },
  { json: { method: 'editMessageText', body: { ...body, message_id: who.messageId } } },
];

// Build the row we save in the "gbu_students" data table.
// The field names must match the table's column names exactly.
const who = $('🧠 Understand message').first().json;
const student = $('👤 Find student').first().json;          // {} if no class picked yet

if (who.action === 'batch') {             // they tapped "Batch 1 / Batch 2 / Not sure"
  if (!student.section_id) return [];     // no class saved yet -> nothing to update
  return [{ json: {
    chat_id: String(who.chatId),
    name: student.name || who.name,
    section_id: student.section_id,
    section: student.section,
    program: student.program,
    school: student.school,
    batch: Number(who.value) || 0,
  } }];
}

// they tapped a class -> look it up in the timetable
const row = JSON.parse($('📥 Fetch GBU timetable').first().json.data)
  .find(r => String(r.Section_Id ?? '').trim() === who.value);
if (!row) return [];                      // that class isn't in the timetable anymore

return [{ json: {
  chat_id: String(who.chatId),
  name: who.name,
  section_id: String(row.Section_Id).trim(),
  section: String(row.SectionName).trim(),
  program: String(row.program_name).trim(),
  school: String(row.school).trim(),
  batch: 0,                               // 0 = "show every batch" until they choose one
} }];

// Tell the student what we saved. If their labs are split into batches, ask which one.
const S = $('⚙️ Settings').first().json;
const who = $('🧠 Understand message').first().json;
const saved = $('📝 Prepare student row').first().json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const button = (text, data) => ({ text, callback_data: data });

// Which lab batches exist for this class? e.g. [1, 2]  (empty = labs aren't split)
const batches = [...new Set(
  JSON.parse($('📥 Fetch GBU timetable').first().json.data)
    .filter(r => String(r.Section_Id ?? '').trim() === saved.section_id)
    .map(r => Number(r.Batch_Id || 0))
    .filter(b => b > 0)
)].sort((a, b) => a - b);

const label = esc(saved.section) + (saved.batch ? `, Batch ${saved.batch}` : '');
const edit = (text, buttons) => ({ json: { method: 'editMessageText', body: {
  chat_id: who.chatId, message_id: who.messageId, text, parse_mode: 'HTML',
  ...(buttons ? { reply_markup: { inline_keyboard: buttons } } : {}),
} } });

const out = [{ json: { method: 'answerCallbackQuery', body: { callback_query_id: who.callbackId } } }];

if (who.action === 'section' && batches.length) {
  out.push(edit(
    `<b>${esc(saved.section)}</b> saved!\n\nLabs in your class are split into batches.\n<b>Which batch are you in?</b>`,
    [batches.map(b => button(`Batch ${b}`, `b:${b}`)), [button('Not sure, show all', 'b:0')]],
  ));
} else {
  out.push(edit(`Class chosen: <b>${label}</b>`));
  out.push({ json: { method: 'sendMessage', body: {
    chat_id: who.chatId,
    parse_mode: 'HTML',
    text: `<b>All set!</b> You're in <b>${label}</b>\n<i>${esc(saved.program)}, ${esc(saved.school)}</i>\n\n` +
          `I'll message you:\n- every morning at ${S.morningAt.replace(/^0/, '')} with the day's classes\n` +
          `- ${S.remindMinutesBefore} minutes before each class\n\n` +
          `Use the buttons below anytime.`,
    // A menu that replaces the phone keyboard. Tapping a button sends its text.
    reply_markup: {
      keyboard: [[{ text: 'Today' }, { text: 'Tomorrow' }],
                 [{ text: 'Next class' }, { text: 'Week' }],
                 [{ text: 'Change class' }]],
      resize_keyboard: true,
      is_persistent: true,
    },
  } } });
}
return out;

// ── Timetable helpers (same logic as timetable.py in the Python repo) ──────────
const S = $('⚙️ Settings').first().json;
const DAY_NAMES = ['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

// One tidy object per class slot. TT_Day: 1 = Monday ... 7 = Sunday. Batch_Id 0 = whole class.
const rows = JSON.parse($('📥 Fetch GBU timetable').first().json.data).map(r => ({
  sectionId: String(r.Section_Id ?? '').trim(),
  day: Number(r.TT_Day),
  period: Number(r.TT_Period),
  batch: Number(r.Batch_Id || 0),
  type: String(r.ActivityTag ?? '').trim() || 'Class',
  code: String(r.Subject_Code ?? '').trim(),
  subject: String(r.subject_name ?? '').trim() || String(r.Subject_Code ?? '').trim() || 'Class',
  teacher: String(r.TeacherName ?? '').trim(),
  room: String(r.RoomName ?? '').trim(),
}));

// Period 2 -> ["09:30", "10:30"], using the table in the Settings node
function periodTimes(p) {
  const fromSettings = (S.periods || [])[p - 1];
  if (fromSettings) return fromSettings.split('-').map(t => t.trim());
  const start = 8 * 60 + 30 + (p - 1) * 60;           // not in the table: website's rule
  const hhmm = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  return [hhmm(start), hhmm(start + 60)];
}

// All classes of one section on one day. Back-to-back periods of the same class
// (like a 2-hour lab) are joined into one. batch 0 = show every lab batch.
function classesOn(sectionId, day, batch) {
  const list = rows
    .filter(r => r.sectionId === String(sectionId) && r.day === day && (!batch || r.batch === 0 || r.batch === batch))
    .sort((a, b) => a.period - b.period || a.batch - b.batch || (a.code < b.code ? -1 : a.code > b.code ? 1 : 0));
  const classes = [];
  const seen = new Set();
  for (const r of list) {
    const what = [r.code, r.subject, r.type, r.teacher, r.room, r.batch].join('|');
    if (seen.has(`${what}@${r.period}`)) continue;      // the API sometimes repeats a row
    seen.add(`${what}@${r.period}`);
    const previous = classes.find(c => c.what === what && c.lastPeriod === r.period - 1);
    if (previous) {
      previous.lastPeriod = r.period;
      previous.end = periodTimes(r.period)[1];
    } else {
      const [start, end] = periodTimes(r.period);
      classes.push({ ...r, what, firstPeriod: r.period, lastPeriod: r.period, start, end });
    }
  }
  return classes.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : a.batch - b.batch));
}

// "09:30" on the same date as `date` (a Luxon DateTime)
const at = (date, hhmm) => date.set({ hour: Number(hhmm.slice(0, 2)), minute: Number(hhmm.slice(3, 5)), second: 0, millisecond: 0 });

// ── Message helpers (same as messages.py) ──────────────────────────────────────
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const whoLabel = st => esc(st.section) + (Number(st.batch) ? `, Batch ${st.batch}` : '');

function card(c, showBatch) {
  const details = [];
  if (c.code) details.push(`<code>${esc(c.code)}</code>`);
  if (c.teacher) details.push(esc(c.teacher));
  if (c.room) details.push(esc(c.room));
  return [
    `<b>${c.start}-${c.end}</b> - ${esc(c.type)}` + (showBatch && c.batch ? ` (Batch ${c.batch})` : ''),
    esc(c.subject),
    details.join(' - '),
  ].filter(Boolean).join('\n');
}

function dayTimetable(st, day, classes, when) {
  const title = `<b>${DAY_NAMES[day]}</b>${when ? ` (${when})` : ''} - ${whoLabel(st)}`;
  if (!classes.length) return `${title}\n\nNo classes!`;
  const parts = [title];
  let busyUntil = null;
  for (const c of classes) {
    if (busyUntil && c.start > busyUntil) parts.push(`<i>Free ${busyUntil}-${c.start}</i>`);
    parts.push(card(c, !Number(st.batch)));
    if (!busyUntil || c.end > busyUntil) busyUntil = c.end;
  }
  return parts.join('\n\n');
}
// ────────────────────────────────────────────────────────────────────────────────

// ── The reply ───────────────────────────────────────────────────────────────────
const who = $('🧠 Understand message').first().json;
const student = $('👤 Find student').first().json;          // {} if no class picked yet

const out = [];
const telegram = (method, body) => out.push({ json: { method, body: { chat_id: who.chatId, parse_mode: 'HTML', ...body } } });
if (who.callbackId) out.push({ json: { method: 'answerCallbackQuery', body: { callback_query_id: who.callbackId } } });

if (!student.section_id) {
  telegram('sendMessage', { text: "You haven't picked your class yet.\nTap /start to choose it." });
  return out;
}

const now = DateTime.now().setZone(S.timezone);
const batch = Number(student.batch) || 0;
const dayButtons = [[1, 2, 3, 4], [5, 6, 7]]
  .map(line => line.map(d => ({ text: DAY_NAMES[d].slice(0, 3), callback_data: `d:${d}` })));

if (who.action === 'week') {                             // show day buttons
  telegram('sendMessage', { text: 'Which day do you want to see?', reply_markup: { inline_keyboard: dayButtons } });

} else if (who.action === 'next') {                      // what's on now, and the next class
  let running = [], nextDate = null, upcoming = [];
  for (let d = 0; d < 8 && !nextDate; d++) {
    const date = now.plus({ days: d });
    let classes = classesOn(student.section_id, date.weekday, batch);
    if (d === 0) {
      running = classes.filter(c => at(date, c.start) <= now && now < at(date, c.end));
      classes = classes.filter(c => at(date, c.start) > now);
    }
    if (classes.length) {
      nextDate = date;
      upcoming = classes.filter(c => c.start === classes[0].start);
    }
  }
  const parts = [];
  if (running.length) parts.push(`<b>Right now</b>\n${running.map(c => card(c, !batch)).join('\n\n')}`);
  if (upcoming.length) {
    const start = at(nextDate, upcoming[0].start);
    const minutes = Math.floor(start.diff(now, 'minutes').minutes);
    const days = Math.round(start.startOf('day').diff(now.startOf('day'), 'days').days);
    const when = days === 0 ? (minutes < 60 ? `in ${Math.max(minutes, 1)} min (${start.toFormat('HH:mm')})` : `today at ${start.toFormat('HH:mm')}`)
               : days === 1 ? `tomorrow at ${start.toFormat('HH:mm')}`
               : `on ${DAY_NAMES[start.weekday]} at ${start.toFormat('HH:mm')}`;
    parts.push(`<b>Next class</b> - ${when}\n${upcoming.map(c => card(c, !batch)).join('\n\n')}`);
  }
  telegram('sendMessage', { text: parts.join('\n\n') || `No classes in the next 7 days for ${whoLabel(student)}.` });

} else {                                                 // today / tomorrow / a day button
  let day = Number(who.value), when = '';
  if (who.action === 'today') { day = now.weekday; when = 'today'; }
  if (who.action === 'tomorrow') { day = now.plus({ days: 1 }).weekday; when = 'tomorrow'; }
  if (!(day >= 1 && day <= 7)) day = now.weekday;
  const text = dayTimetable(student, day, classesOn(student.section_id, day, batch), when);
  if (who.action === 'day') telegram('editMessageText', { message_id: who.messageId, text, reply_markup: { inline_keyboard: dayButtons } });
  else telegram('sendMessage', { text });
}
return out;

// The student sent /stop. Their row is already deleted, so say bye and hide the menu.
const who = $('🧠 Understand message').first().json;
return [{ json: { method: 'sendMessage', body: {
  chat_id: who.chatId,
  parse_mode: 'HTML',
  text: "Done, I've forgotten your class and won't message you.\nTap /start anytime to come back.",
  reply_markup: { remove_keyboard: true },
} } }];

// Anything we don't understand gets the help text.
const who = $('🧠 Understand message').first().json;
const out = [];
if (who.callbackId) out.push({ json: { method: 'answerCallbackQuery', body: { callback_query_id: who.callbackId } } });
out.push({ json: { method: 'sendMessage', body: {
  chat_id: who.chatId,
  parse_mode: 'HTML',
  text: '<b>GBU Timetable Bot</b>\n' +
        'I send your class timetable and remind you before every class.\n\n' +
        '/start - choose your class\n' +
        '/today - today\'s classes\n' +
        '/tomorrow - tomorrow\'s classes\n' +
        '/next - your next class\n' +
        '/week - pick any day\n' +
        '/stop - stop all messages\n\n' +
        'You can also just type your class name, like <code>BCS-I-A</code>.',
} } });
return out;

// The clock ticks every 5 minutes. Is it time to send something?
// If not, we stop right here - nothing gets downloaded. Uses Indian time, whatever n8n's own timezone is.
const S = $('⚙️ Settings').first().json;
const now = DateTime.now().setZone(S.timezone);
const minutesNow = now.hour * 60 + now.minute;
const toMinutes = hhmm => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));

// Morning summary: the tick at 7:30 (the window is 5 minutes wide, so it happens once a day)
const morning = toMinutes(S.morningAt);
if (minutesNow >= morning && minutesNow < morning + 5) {
  return [{ json: { job: 'morning summary', time: now.toFormat('HH:mm') } }];
}

// Reminder: does a period start in about `remindMinutesBefore` minutes?
const startingSoon = (S.periods || [])
  .map((times, i) => ({ period: i + 1, start: times.split('-')[0].trim() }))
  .filter(p => {
    const minutesUntil = toMinutes(p.start) - minutesNow;
    return minutesUntil > S.remindMinutesBefore - 5 && minutesUntil <= S.remindMinutesBefore;
  });
if (startingSoon.length) {
  return [{ json: { job: 'class reminder', time: now.toFormat('HH:mm'), periods: startingSoon.map(p => p.period) } }];
}

return [];   // nothing due -> the workflow stops here

// ── Timetable helpers (same logic as timetable.py in the Python repo) ──────────
const S = $('⚙️ Settings').first().json;
const DAY_NAMES = ['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

// One tidy object per class slot. TT_Day: 1 = Monday ... 7 = Sunday. Batch_Id 0 = whole class.
const rows = JSON.parse($('📥 Fetch timetable (for reminders)').first().json.data).map(r => ({
  sectionId: String(r.Section_Id ?? '').trim(),
  day: Number(r.TT_Day),
  period: Number(r.TT_Period),
  batch: Number(r.Batch_Id || 0),
  type: String(r.ActivityTag ?? '').trim() || 'Class',
  code: String(r.Subject_Code ?? '').trim(),
  subject: String(r.subject_name ?? '').trim() || String(r.Subject_Code ?? '').trim() || 'Class',
  teacher: String(r.TeacherName ?? '').trim(),
  room: String(r.RoomName ?? '').trim(),
}));

// Period 2 -> ["09:30", "10:30"], using the table in the Settings node
function periodTimes(p) {
  const fromSettings = (S.periods || [])[p - 1];
  if (fromSettings) return fromSettings.split('-').map(t => t.trim());
  const start = 8 * 60 + 30 + (p - 1) * 60;           // not in the table: website's rule
  const hhmm = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  return [hhmm(start), hhmm(start + 60)];
}

// All classes of one section on one day. Back-to-back periods of the same class
// (like a 2-hour lab) are joined into one. batch 0 = show every lab batch.
function classesOn(sectionId, day, batch) {
  const list = rows
    .filter(r => r.sectionId === String(sectionId) && r.day === day && (!batch || r.batch === 0 || r.batch === batch))
    .sort((a, b) => a.period - b.period || a.batch - b.batch || (a.code < b.code ? -1 : a.code > b.code ? 1 : 0));
  const classes = [];
  const seen = new Set();
  for (const r of list) {
    const what = [r.code, r.subject, r.type, r.teacher, r.room, r.batch].join('|');
    if (seen.has(`${what}@${r.period}`)) continue;      // the API sometimes repeats a row
    seen.add(`${what}@${r.period}`);
    const previous = classes.find(c => c.what === what && c.lastPeriod === r.period - 1);
    if (previous) {
      previous.lastPeriod = r.period;
      previous.end = periodTimes(r.period)[1];
    } else {
      const [start, end] = periodTimes(r.period);
      classes.push({ ...r, what, firstPeriod: r.period, lastPeriod: r.period, start, end });
    }
  }
  return classes.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : a.batch - b.batch));
}

// "09:30" on the same date as `date` (a Luxon DateTime)
const at = (date, hhmm) => date.set({ hour: Number(hhmm.slice(0, 2)), minute: Number(hhmm.slice(3, 5)), second: 0, millisecond: 0 });

// ── Message helpers (same as messages.py) ──────────────────────────────────────
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const whoLabel = st => esc(st.section) + (Number(st.batch) ? `, Batch ${st.batch}` : '');

function card(c, showBatch) {
  const details = [];
  if (c.code) details.push(`<code>${esc(c.code)}</code>`);
  if (c.teacher) details.push(esc(c.teacher));
  if (c.room) details.push(esc(c.room));
  return [
    `<b>${c.start}-${c.end}</b> - ${esc(c.type)}` + (showBatch && c.batch ? ` (Batch ${c.batch})` : ''),
    esc(c.subject),
    details.join(' - '),
  ].filter(Boolean).join('\n');
}

function dayTimetable(st, day, classes, when) {
  const title = `<b>${DAY_NAMES[day]}</b>${when ? ` (${when})` : ''} - ${whoLabel(st)}`;
  if (!classes.length) return `${title}\n\nNo classes!`;
  const parts = [title];
  let busyUntil = null;
  for (const c of classes) {
    if (busyUntil && c.start > busyUntil) parts.push(`<i>Free ${busyUntil}-${c.start}</i>`);
    parts.push(card(c, !Number(st.batch)));
    if (!busyUntil || c.end > busyUntil) busyUntil = c.end;
  }
  return parts.join('\n\n');
}
// ────────────────────────────────────────────────────────────────────────────────

// ── Who gets what ───────────────────────────────────────────────────────────────
const due = $('🕐 Anything due now?').first().json;   // { job, periods }
const now = DateTime.now().setZone(S.timezone);
const today = now.weekday;

const out = [];
const seen = new Set();                                  // never message the same chat twice
for (const { json: student } of $input.all()) {
  if (!student.section_id || seen.has(student.chat_id)) continue;
  seen.add(student.chat_id);
  const batch = Number(student.batch) || 0;
  const classes = classesOn(student.section_id, today, batch);
  let text = null;

  if (due.job === 'morning summary') {
    if (classes.length) {                                // no classes today -> don't disturb them
      text = `<b>Good morning, ${esc(student.name || 'there')}!</b> Here's your day:\n\n` +
             dayTimetable(student, today, classes);
    }
  } else {
    // Only classes that START in these periods (the 2nd hour of a lab is not a new class)
    const soon = classes.filter(c => due.periods.includes(c.firstPeriod));
    if (soon.length) {
      const minutes = Math.ceil(at(now, soon[0].start).diff(now, 'minutes').minutes);
      text = (minutes > 1 ? `<b>Class in ${minutes} minutes!</b>` : '<b>Class starting now!</b>') +
             '\n\n' + soon.map(c => card(c, !batch)).join('\n\n');
    }
  }

  if (text) out.push({ json: { method: 'sendMessage', body: { chat_id: student.chat_id, text, parse_mode: 'HTML' } } });
}
return out;
